// P9-28 — the figure engine is MuPDF's own WASM build, run in Node. Every PDF
// here is generated by `figure-pdf.test-helper.ts` and invented; the owner's
// paper is never a fixture and no image of it is anywhere in the repository.

import { afterEach, beforeAll, describe, expect, it, vi } from "vitest";
import {
  CHART_CAPTION,
  PANEL_ONE,
  PANEL_TWO,
  RASTER_CAPTION,
  fixtures,
  pngInfo,
} from "./figure-pdf.test-helper";
import {
  EXTRACTION_BUDGET_MS,
  MAX_CONCURRENT_EXTRACTIONS,
  MAX_PDF_BYTES,
  extractPdfFigures,
} from "./pdf-engine";

const OPTIONS = { maxPages: 24, maxFigures: 12 };
const { chart: chartPdf, twoPanel: twoPanelPdf, paper: paperPdf, textOnly: textOnlyPdf, uncaptioned: uncaptionedPdf, hugeFigure: hugeFigurePdf } = fixtures;

const near = (actual: number, expected: number, tolerance = 1) =>
  expect(Math.abs(actual - expected)).toBeLessThanOrEqual(tolerance);

describe("the fixtures", () => {
  it("stay tiny (each PDF is at most 5 KB)", () => {
    for (const pdf of [chartPdf, twoPanelPdf, paperPdf, textOnlyPdf, uncaptionedPdf, hugeFigurePdf]) {
      expect(pdf.byteLength).toBeLessThanOrEqual(5_000);
    }
  });
});

describe("extractPdfFigures: what it finds", () => {
  it("finds a vector figure with its caption and a box on the drawn extent", async () => {
    const { figures, reason } = await extractPdfFigures(chartPdf, OPTIONS);
    expect(reason).toBeNull();
    expect(figures).toHaveLength(1);
    const [figure] = figures;
    expect(figure.ordinal).toBe(0);
    expect(figure.page).toBe(1);
    expect(figure.kind).toBe("drawing");
    expect(figure.caption).toBe(CHART_CAPTION);
    // The drawn extent, to the point: the axes and the curve's control point
    // (PyMuPDF's own rule for a path's box), not the stroke's widened hull.
    expect(figure.box).toBeDefined();
    const [x0, y0, x1, y1] = figure.box!;
    near(x0, 110);
    near(y0, 240);
    near(x1, 380);
    near(y1, 400);
  });

  it("returns a real PNG, the box plus 10 pt of padding at 2.8x", async () => {
    const { figures } = await extractPdfFigures(chartPdf, OPTIONS);
    const info = pngInfo(figures[0].png);
    expect(info.signature).toBe(true);
    // (270 + 20) x (160 + 20) pt at 2.8: 812 x 504, PyMuPDF's own size for it.
    near(info.width, 812, 2);
    near(info.height, 504, 2);
  });

  it("splits two captioned figures on one page, each with its own caption", async () => {
    const { figures } = await extractPdfFigures(twoPanelPdf, OPTIONS);
    expect(figures.map((f) => f.ordinal)).toEqual([0, 1]);
    expect(figures.map((f) => f.caption)).toEqual([PANEL_ONE, PANEL_TWO]);
    expect(figures.every((f) => f.page === 1 && f.kind === "drawing")).toBe(true);
    near(figures[0].box![1], 80);
    near(figures[0].box![3], 240);
    near(figures[1].box![1], 330);
    near(figures[1].box![3], 490);
  });

  it("finds a raster as an image figure, with its caption", async () => {
    const { figures } = await extractPdfFigures(paperPdf, { ...OPTIONS, onlyPage: 2 });
    expect(figures).toHaveLength(1);
    const [figure] = figures;
    expect(figure.kind).toBe("image");
    expect(figure.page).toBe(2);
    expect(figure.caption).toBe(RASTER_CAPTION);
    expect(figure.box!.map(Math.round)).toEqual([100, 150, 300, 350]);
    const info = pngInfo(figure.png);
    expect(info.signature).toBe(true);
    near(info.width, 616, 2); // (200 + 20) pt at 2.8
    near(info.height, 616, 2);
  });

  it("numbers figures through the whole document, in page order", async () => {
    const { figures } = await extractPdfFigures(paperPdf, OPTIONS);
    expect(figures.map((f) => [f.ordinal, f.page, f.kind])).toEqual([
      [0, 2, "image"],
      [1, 3, "drawing"],
      [2, 4, "drawing"],
      [3, 4, "drawing"],
    ]);
  });

  it("answers a page with nothing to extract with a reason and no figure", async () => {
    const { figures, reason } = await extractPdfFigures(textOnlyPdf, OPTIONS);
    expect(figures).toEqual([]);
    expect(reason).toMatch(/did not find any figure regions/);
  });

  it("does not take a drawing for a figure unless a \"Figure N\" caption opens beside it", async () => {
    const { figures, reason } = await extractPdfFigures(uncaptionedPdf, OPTIONS);
    expect(figures).toEqual([]);
    expect(reason).not.toBeNull();
  });

  it("answers bytes that are not a PDF with a reason, not a throw", async () => {
    const { figures, reason } = await extractPdfFigures(new TextEncoder().encode("this is not a pdf"), OPTIONS);
    expect(figures).toEqual([]);
    expect(reason).toMatch(/PDF figure extraction failed/);
  });
});

describe("extractPdfFigures: the caps", () => {
  it("stops at maxFigures", async () => {
    const { figures } = await extractPdfFigures(twoPanelPdf, { maxPages: 24, maxFigures: 1 });
    expect(figures).toHaveLength(1);
    expect(figures[0].caption).toBe(PANEL_ONE);
  });

  it("reads only the first maxPages pages", async () => {
    const { figures } = await extractPdfFigures(paperPdf, { maxPages: 2, maxFigures: 12 });
    expect(figures.map((f) => f.page)).toEqual([2]);
  });

  it("refuses a PDF over 18,000,000 bytes before it parses a byte of it", async () => {
    const { figures, reason } = await extractPdfFigures(new Uint8Array(MAX_PDF_BYTES + 1), OPTIONS);
    expect(MAX_PDF_BYTES).toBe(18_000_000);
    expect(figures).toEqual([]);
    expect(reason).toMatch(/too large/);
  });

  it("scales a render down to at most 4.5 megapixels", async () => {
    const { figures } = await extractPdfFigures(hugeFigurePdf, OPTIONS);
    expect(figures).toHaveLength(1);
    const { width, height } = pngInfo(figures[0].png);
    expect(width * height).toBeLessThanOrEqual(4_500_000);
    // Dropped in 0.2 steps from 2.8, not crushed: 2.4x is 3.9 Mpx.
    expect(width * height).toBeGreaterThan(3_000_000);
  });
});

describe("extractPdfFigures: onlyPage and label", () => {
  it("onlyPage reads that page and no other", async () => {
    const { figures } = await extractPdfFigures(paperPdf, { ...OPTIONS, onlyPage: 3 });
    expect(figures.map((f) => [f.page, f.kind])).toEqual([[3, "drawing"]]);
  });

  it("label picks the region whose caption opens with that figure number", async () => {
    const { figures } = await extractPdfFigures(paperPdf, { ...OPTIONS, label: "Figure 2" });
    expect(figures).toHaveLength(1);
    expect(figures[0].page).toBe(3);
    expect(figures[0].caption).toMatch(/^Figure 2\./);
  });

  it("onlyPage and label together pick one of two figures on a page", async () => {
    const { figures } = await extractPdfFigures(paperPdf, { ...OPTIONS, onlyPage: 4, label: "Figure 10" });
    expect(figures).toHaveLength(1);
    expect(figures[0].caption).toBe(PANEL_TWO);
    near(figures[0].box![1], 330);
  });

  it("takes the label as the bare number or as \"Fig. N\", in any case", async () => {
    for (const label of ["10", "fig. 10", "FIGURE 10", " Figure  10 "]) {
      const { figures } = await extractPdfFigures(paperPdf, { ...OPTIONS, label });
      expect(figures.map((f) => f.caption), label).toEqual([PANEL_TWO]);
    }
  });

  it("does not take \"Figure 1\" for the caption of Figure 10", async () => {
    const { figures } = await extractPdfFigures(paperPdf, { ...OPTIONS, label: "Figure 1" });
    expect(figures.map((f) => f.caption)).toEqual([RASTER_CAPTION]);
  });

  it("answers a label no caption carries with a reason that names it", async () => {
    const { figures, reason } = await extractPdfFigures(paperPdf, { ...OPTIONS, label: "Figure 9" });
    expect(figures).toEqual([]);
    expect(reason).toMatch(/Figure 9/);
  });

  it("answers a page the PDF does not have with a reason", async () => {
    const { figures, reason } = await extractPdfFigures(paperPdf, { ...OPTIONS, onlyPage: 9 });
    expect(figures).toEqual([]);
    expect(reason).toMatch(/page 9/);
  });

  it("does not read a page past maxPages even when it is asked for", async () => {
    const { figures } = await extractPdfFigures(paperPdf, { maxPages: 2, maxFigures: 12, onlyPage: 3 });
    expect(figures).toEqual([]);
  });
});

/** Counts every live MuPDF object (the wrappers register with a
 *  FinalizationRegistry on construction and unregister on `destroy()`), so a
 *  missed `destroy()` is seen as an object still alive when the call returns. */
function watchMupdfObjects() {
  const live = new Map<WeakKey, string>();
  let mostDocuments = 0;
  const register = FinalizationRegistry.prototype.register;
  const unregister = FinalizationRegistry.prototype.unregister;
  vi.spyOn(FinalizationRegistry.prototype, "register").mockImplementation(function (
    this: FinalizationRegistry<unknown>,
    target: WeakKey,
    held: unknown,
    token?: WeakKey,
  ) {
    const name = (target as { constructor: { name: string } }).constructor.name;
    live.set(target, name);
    mostDocuments = Math.max(mostDocuments, [...live.values()].filter((n) => /Document$/.test(n)).length);
    return register.call(this, target, held, token);
  });
  vi.spyOn(FinalizationRegistry.prototype, "unregister").mockImplementation(function (
    this: FinalizationRegistry<unknown>,
    token: WeakKey,
  ) {
    live.delete(token);
    return unregister.call(this, token);
  });
  return {
    alive: () => [...live.values()].sort(),
    mostDocuments: () => mostDocuments,
  };
}

describe("extractPdfFigures: MuPDF objects and concurrency", () => {
  beforeAll(async () => {
    await import("mupdf"); // its own singletons (the colour spaces) exist before any watch starts
  });
  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("destroys every Document, Page, StructuredText, Pixmap and Device it makes", async () => {
    const watch = watchMupdfObjects();
    await extractPdfFigures(paperPdf, OPTIONS);
    await extractPdfFigures(paperPdf, { ...OPTIONS, onlyPage: 4, label: "Figure 3" });
    await extractPdfFigures(textOnlyPdf, OPTIONS);
    await extractPdfFigures(new TextEncoder().encode("this is not a pdf"), OPTIONS);
    expect(watch.mostDocuments()).toBeGreaterThan(0); // the watch saw the engine work
    expect(watch.alive()).toEqual([]);
  });

  it("runs at most two extractions at once in one instance", async () => {
    expect(MAX_CONCURRENT_EXTRACTIONS).toBe(2);
    const watch = watchMupdfObjects();
    const results = await Promise.all(Array.from({ length: 6 }, () => extractPdfFigures(paperPdf, OPTIONS)));
    expect(watch.mostDocuments()).toBe(2);
    for (const { figures } of results) expect(figures.map((f) => f.page)).toEqual([2, 3, 4, 4]);
    expect(watch.alive()).toEqual([]);
  });

  it("stops reading pages when its time budget is spent, and keeps the figures it has", async () => {
    const mupdf = await import("mupdf");
    let elapsed = 0;
    vi.spyOn(performance, "now").mockImplementation(() => elapsed);
    const openDocument = mupdf.Document.openDocument.bind(mupdf.Document);
    vi.spyOn(mupdf.Document, "openDocument").mockImplementation((...args: Parameters<typeof openDocument>) => {
      const doc = openDocument(...args);
      const loadPage = doc.loadPage.bind(doc);
      let loaded = 0;
      doc.loadPage = (index: number) => {
        loaded += 1;
        if (loaded === 3) elapsed = EXTRACTION_BUDGET_MS + 1; // the budget is spent as page 3 opens
        return loadPage(index);
      };
      return doc;
    });
    const { figures, reason } = await extractPdfFigures(paperPdf, OPTIONS);
    // Page 2's figure was made in time; page 3 opened with the budget spent,
    // so its chart is not rendered and page 4 is not opened.
    expect(figures.map((f) => f.page)).toEqual([2]);
    expect(reason).toMatch(/stopped reading this PDF after 25 s, with 1 figure found so far/);
  });
});
